def transform_detailed(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]

    ones = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 1]

    for sr, sc in ones:
        # Up-left: (r-1, c-1)
        for r in range(sr - 1, -1, -1):
            c = sc - (sr - r)
            if c >= 0:
                output[r][c] = 1
        # Down-right: (r+1, c+1)
        for r in range(sr + 1, rows):
            c = sc + (r - sr)
            if c < cols:
                output[r][c] = 1
        # Up-right: (r-1, c+1)
        for r in range(sr - 1, -1, -1):
            c = sc + (sr - r)
            if c < cols:
                output[r][c] = 1
        # Down-left: (r+1, c-1)
        for r in range(sr + 1, rows):
            c = sc - (r - sr)
            if c >= 0:
                output[r][c] = 1

    return output

