def transform_by_number(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]

    # Find background value (most common)
    from collections import Counter
    vals = [grid[r][c] for r in range(rows) for c in range(cols)]
    bg_value = max(set(vals), key=vals.count)
    print(f"Background value: {bg_value}")

    # Direction mappings
    # 1 -> down-right
    # 3 -> up-left and down-left
    # 4 -> up-right and down-right
    def extend_1(grid, rows, cols, sr, sc, output):
        for r in range(sr + 1, rows):
            c = sc + (r - sr)
            if c < cols:
                output[r][c] = 1

    def extend_3_lr(grid, rows, cols, sr, sc, output, direction):
        if direction == 'ul':  # up-left
            for r in range(sr - 1, -1, -1):
                c = sc - (sr - r)
                if c >= 0:
                    output[r][c] = 3
        elif direction == 'dl':  # down-left
            for r in range(sr + 1, rows):
                c = sc - (r - sr)
                if c >= 0:
                    output[r][c] = 3
        elif direction == 'ur':  # up-right
            for r in range(sr - 1, -1, -1):
                c = sc + (sr - r)
                if c < cols:
                    output[r][c] = 3
        elif direction == 'dr':  # down-right
            for r in range(sr + 1, rows):
                c = sc + (r - sr)
                if c < cols:
                    output[r][c] = 3

    # Process each non-background, non-zero value
    for sr in range(rows):
        for sc in range(cols):
            val = output[sr][sc]
            if val not in [bg_value, 0]:
                if val == 1:
                    print(f"Extending 1 at ({sr}, {sc}) down-right")
                    extend_1(output, rows, cols, sr, sc, output)
                elif val == 3:
                    print(f"Extending 3 at ({sr}, {sc}) in all diagonal directions")
                    extend_3_lr(output, rows, cols, sr, sc, output, 'ul')
                    extend_3_lr(output, rows, cols, sr, sc, output, 'dl')
                    extend_3_lr(output, rows, cols, sr, sc, output, 'ur')
                    extend_3_lr(output, rows, cols, sr, sc, output, 'dr')
                elif val == 4:
                    print(f"Extending 4 at ({sr}, {sc}) in right diagonal directions")
                    extend_3_lr(output, rows, cols, sr, sc, output, 'ur')
                    extend_3_lr(output, rows, cols, sr, sc, output, 'dr')

    return output

