# Re-implement the transform with the correct rules based on verified demos
# Rules from verified demos:
# - 1: down-right (+1,+1) only
# - 3: two left diagonals (-1,-1) and (+1,-1)  [from Demo 2]
# - 4: two right diagonals (-1,+1) and (+1,+1)  [inferred from Demo 2]

# For 2 (unknown from demos), I'll assume it behaves like 4 (two right diagonals)
# since both are even numbers and 3/behaves like 3 (two left diagonals)

BG = 9  # Background for test input
SPECIAL_RULES = {
    1: [1, 1],       # down-right only
    2: [(-1, 1), (1, 1)],  # two right diagonals (same as 4)
    3: [(-1,-1), (1,-1)],  # two left diagonals
    4: [(-1, 1), (1, 1)],  # two right diagonals
}

def transform(test_input):
    rows, cols = len(test_input), len(test_input[0])
    output = [[BG for _ in range(cols)] for _ in range(rows)]
    special_positions = []

    # Find all special numbers (not background, not 0)
    for r in range(rows):
        for c in range(cols):
            val = test_input[r][c]
            if val not in (BG, 0) and val in SPECIAL_RULES:
                special_positions.append((r, c, val))

    # Extend each special number in its diagonal pattern
    # Build dict of positions per (r,c) to handle overwrites
    final_positions = {}
    for r_start, c_start, val in special_positions:
        directions = SPECIAL_RULES.get(val)
        if directions:
            dr, dc = directions
            for i in range(1, max(rows, cols)):
                nr, nc = r_start + dr * i, c_start + dc * i
                if 0 <= nr < rows and 0 <= nc < cols:
                    final_positions[(nr, nc)] = (val, i)
                else:
                    break

    # Fill output grid (keep original positions, add extended positions)
    for r_start, c_start, val in special_positions:
        output[r_start][c_start] = val

    for (r, c), (v, i) in final_positions.items():
        output[r][c] = v

    return output

# Run on test input
result = transform(test_input)
print("=== Result (9x18 grid) ===")
