def transform_v2(grid):
    rows, cols = len(grid), len(grid[0])
    output = [[bg for _ in range(cols)] for _ in range(rows)]

    # Collect all special positions by value
    positions_by_value = {v: [] for v in special_rules}

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val in special_rules:
                positions_by_value[val].append((r, c))

    # Save ALL original positions first (to output grid)
    for r in range(rows):
        for c in range(cols):
            for val in special_rules:
                if (r, c) in positions_by_value[val]:
                    output[r][c] = val

    # Now extend each number WITHOUT overwriting originals
    for val, positions in positions_by_value.items():
        directions = special_rules[val]
        for r_start, c_start in positions:
            for dr, dc in directions:
                i = 1  # Start from distance 1, not the original position
                while True:
                    nr, nc = r_start + dr * i, c_start + dc * i
                    if 0 <= nr < rows and 0 <= nc < cols:
                        # Don't overwrite the original starting position for distance 0
                        # But for distance > 0, we can overwrite whatever is there
                        output[nr][nc] = val
                        i += 1
                    else:
                        break

    return output

